if MOD == "re":
    import re as R
else:
    import pyre as R
from cases import CASES

def flags(spec):
    f = 0
    for ch in spec:
        f |= getattr(R, ch)
    return f

for op, pat, fs, subj, extra in CASES:
    tag = op + " " + repr(pat) + " " + fs + " " + repr(subj)
    try:
        f = flags(fs)
        if op == "findall":
            r = repr(R.findall(pat, subj, f))
        elif op == "finditer":
            r = repr([(m.span(), m.group(0)) for m in R.finditer(pat, subj, f)])
        elif op == "split":
            r = repr(R.split(pat, subj, 0, f))
        elif op == "sub":
            r = repr(R.sub(pat, extra, subj, 0, f))
        elif op == "subn":
            r = repr(R.subn(pat, extra, subj, 0, f))
        else:
            m = getattr(R, op)(pat, subj, f)
            if m is None:
                r = "None"
            elif extra == "span":
                r = repr(m.span())
            else:
                r = repr(m.group(0))
    except NotImplementedError as e:
        r = "UNSUPPORTED " + str(e)
    except Exception as e:
        r = "ERR " + type(e).__name__ + ": " + str(e)
    print(tag + "  ==>  " + r)
